    return Nack(self.promised)

def on_accept(self, n, v):
    if n >= self.promised:
        self.accepted_n, self.accepted_v = n, v
        self.disk.write("accepted", (n, v))
        self.promised = n
        return Accepted(n)
    return Nack(self.promised)

